```json
{
  "root_causes": [
    {
      "service": "cart",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, count(*) cart_spans FROM normal_traces WHERE service_name='cart' UNION ALL SELECT 'abnormal', count(*) FROM abnormal_traces WHERE service_name='cart'",
          "claim": "Cart emitted 448 spans in the normal period and zero spans in the abnormal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'abn_frontend_to_cart_err' k, count(*) n FROM abnormal_traces WHERE span_name LIKE '%CartService%' AND attr_status_code='Error' AND service_name='frontend' UNION ALL SELECT 'abn_frontend_to_cart_total', count(*) FROM abnormal_traces WHERE span_name LIKE '%CartService%' AND service_name='frontend' UNION ALL SELECT 'norm_frontend_to_cart_err', count(*) FROM normal_traces WHERE span_name LIKE '%CartService%' AND attr_status_code='Error' AND service_name='frontend'",
          "claim": "All 106 frontend calls to CartService failed in the abnormal period versus none in the normal period."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) n, avg(duration)/1e6 ms FROM abnormal_traces WHERE span_name LIKE '%CartService/GetCart%' AND service_name='checkout' GROUP BY ALL",
          "claim": "Checkout's GetCart calls to cart all end in Error within about 0.14 ms, consistent with cart being unreachable."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name pod, metric, avg(value) v FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'cart%' AND metric IN ('container.memory.working_set','container.cpu.usage') GROUP BY ALL",
          "claim": "Cart pod memory working set and CPU usage collapsed to near zero during the abnormal period, consistent with no live request processing."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "cart",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='checkout' GROUP BY ALL",
          "claim": "Checkout's CartService/GetCart client calls return Error, and 44 of 66 checkout spans are errors."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('POST /api/checkout','grpc.oteldemo.CheckoutService/PlaceOrder') GROUP BY ALL",
          "claim": "Frontend POST /api/checkout and PlaceOrder calls return 500 errors in the abnormal period, 22 each."
        }
      ]
    },
    {
      "from": "cart",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend' AND span_name LIKE '%CartService%' GROUP BY ALL",
          "claim": "Frontend's direct CartService AddItem and GetCart client calls all fail with Error status."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='ingress' AND attr_status_code='Error' GROUP BY ALL",
          "claim": "Frontend-proxy ingress returns HTTP 500 for 156 requests in the abnormal period, forwarded from frontend errors."
        }
      ]
    }
  ]
}
```

